// Minimal standard entry point
int main(void);

// Standard arguments (Command Line Interface)
// argc: Argument count (always >= 1)
// argv: Array of string arguments (char**)
int main(int argc, char **argv);

// POSIX/UNIX Environment (Optional, less portable)
// envp: Array of environment variables
int main(int argc, char **argv, char **envp);

// Return value: Integer exit status (0 = EXIT_SUCCESS)
// Any other value signals failure to the OS
// Use EXIT_SUCCESS/FAILURE from <stdlib.h>
return 0;
